create table public.platform_administrators(
 user_id uuid primary key references auth.users(id)on delete cascade,
 role text not null check(role in('super_admin','platform_admin','support_admin','read_only')),
 status text not null default'active'check(status in('invited','active','suspended')),
 granted_by uuid references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create trigger set_updated_at before update on public.platform_administrators for each row execute function private.set_updated_at();

create function private.is_platform_administrator(required_roles text[]default array['super_admin','platform_admin','support_admin','read_only'])returns boolean
language sql stable security definer set search_path=''as $$select exists(select 1 from public.platform_administrators administrator where administrator.user_id=(select auth.uid())and administrator.status='active'and administrator.role=any(required_roles));$$;

create table public.platform_admin_audit_events(
 id uuid primary key default gen_random_uuid(),actor_user_id uuid references auth.users(id)on delete set null,
 action text not null check(action~'^[a-z][a-z0-9_.-]{0,99}$'),entity_type text not null check(entity_type~'^[a-z][a-z0-9_.-]{0,99}$'),entity_id text,
 before_data jsonb check(before_data is null or jsonb_typeof(before_data)='object'),after_data jsonb check(after_data is null or jsonb_typeof(after_data)='object'),
 source text not null default'user'check(source in('user','system','api')),ip_metadata jsonb not null default'{}'check(jsonb_typeof(ip_metadata)='object'),occurred_at timestamptz not null default clock_timestamp()
);
create index platform_admin_audit_time_idx on public.platform_admin_audit_events(occurred_at desc,id desc);
create index platform_admin_audit_entity_idx on public.platform_admin_audit_events(entity_type,entity_id,occurred_at desc);

create table public.platform_feature_flags(
 key text primary key check(key~'^[a-z][a-z0-9_]{0,79}$'),name text not null check(char_length(btrim(name))between 1 and 120),description text not null default'',
 is_enabled boolean not null default false,rollout_percentage smallint not null default 0 check(rollout_percentage between 0 and 100),conditions jsonb not null default'{}'check(jsonb_typeof(conditions)='object'),
 updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create trigger set_updated_at before update on public.platform_feature_flags for each row execute function private.set_updated_at();
create table public.platform_business_feature_overrides(
 organization_id uuid not null references public.organizations(id)on delete cascade,feature_key text not null references public.platform_feature_flags(key)on delete cascade,
 state text not null check(state in('enabled','disabled')),reason text not null check(char_length(btrim(reason))between 1 and 500),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(organization_id,feature_key)
);
create trigger set_updated_at before update on public.platform_business_feature_overrides for each row execute function private.set_updated_at();

create table public.platform_ai_usage_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,
 feature text not null check(feature~'^[a-z][a-z0-9_]{0,79}$'),model text not null check(char_length(btrim(model))between 1 and 120),request_count integer not null default 1 check(request_count>0),input_tokens bigint not null default 0 check(input_tokens>=0),output_tokens bigint not null default 0 check(output_tokens>=0),
 occurred_at timestamptz not null default clock_timestamp(),metadata jsonb not null default'{}'check(jsonb_typeof(metadata)='object'and not(metadata?|array['prompt','response','content','messages']))
);
create index platform_ai_usage_business_time_idx on public.platform_ai_usage_events(organization_id,occurred_at desc);

create table public.platform_health_checks(
 service text primary key check(service~'^[a-z][a-z0-9_]{0,79}$'),status text not null check(status in('healthy','degraded','down','unknown')),message text not null default''check(char_length(message)<=500),metrics jsonb not null default'{}'check(jsonb_typeof(metrics)='object'),checked_at timestamptz not null default clock_timestamp(),updated_by uuid references auth.users(id)
);
insert into public.platform_health_checks(service,status,message)values('database','healthy','Database migration is current.'),('authentication','unknown','Awaiting external health probe.'),('ai_gateway','unknown','Awaiting provider health integration.'),('email_delivery','unknown','Awaiting provider health integration.');

create table public.platform_support_access_requests(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,requested_by uuid not null references auth.users(id),
 reason text not null check(char_length(btrim(reason))between 20 and 1000),requested_scopes text[]not null check(cardinality(requested_scopes)between 1 and 20),expires_at timestamptz not null check(expires_at>created_at and expires_at<=created_at+interval'24 hours'),
 status text not null default'requested'check(status in('requested','approved_pending_customer','rejected','cancelled','expired')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,
 customer_approved_by uuid references auth.users(id),customer_approved_at timestamptz,access_enabled boolean not null default false check(not access_enabled),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 check(requested_by is distinct from reviewed_by),check((status in('approved_pending_customer','rejected'))=(reviewed_by is not null and reviewed_at is not null))
);
create index support_access_status_idx on public.platform_support_access_requests(status,created_at desc);
comment on column public.platform_support_access_requests.access_enabled is'Safety fuse: this architecture records review intent but is deliberately not connected to tenant RLS. Platform staff receive no customer-data access.';

create function private.write_platform_admin_audit(requested_action text,requested_entity text,requested_entity_id text,requested_before jsonb,requested_after jsonb)returns uuid
language plpgsql security definer set search_path=''as $$declare target uuid:=gen_random_uuid();begin insert into public.platform_admin_audit_events(id,actor_user_id,action,entity_type,entity_id,before_data,after_data,ip_metadata)values(target,(select auth.uid()),requested_action,requested_entity,requested_entity_id,private.sanitize_audit_json(requested_before),private.sanitize_audit_json(requested_after),private.audit_request_metadata());return target;end$$;
create function private.reject_platform_audit_mutation()returns trigger language plpgsql set search_path=''as $$begin raise exception'Platform audit events are immutable.'using errcode='P0001';end$$;
create trigger platform_admin_audit_immutable before update or delete on public.platform_admin_audit_events for each row execute function private.reject_platform_audit_mutation();

create function public.platform_admin_dashboard()returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin
 if not private.is_platform_administrator()then raise exception'Permission denied.'using errcode='42501';end if;
 select jsonb_build_object(
  'businesses',(select coalesce(jsonb_agg(jsonb_build_object('id',organization.id,'name',organization.display_name,'slug',organization.slug,'industry',organization.industry_code,'status',organization.status,'createdAt',organization.created_at,'plan',subscription.plan_key,'subscriptionStatus',subscription.status)order by organization.created_at desc),'[]')from public.organizations organization left join public.subscriptions subscription on subscription.organization_id=organization.id),
  'modules',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'key',key,'name',name,'category',category,'version',version,'status',status,'minimumPlan',minimum_plan)order by name),'[]')from public.module_definitions),
  'templates',(select coalesce(jsonb_agg(jsonb_build_object('id',template.id,'key',template.key,'name',template.name,'industry',template.industry_code,'status',template.status,'versionCount',(select count(*)from public.business_os_template_versions version where version.template_id=template.id),'latestVersion',(select max(version.version)from public.business_os_template_versions version where version.template_id=template.id))order by template.name),'[]')from public.business_os_templates template),
  'templateVersions',(select coalesce(jsonb_agg(jsonb_build_object('id',version.id,'templateId',version.template_id,'templateName',template.name,'version',version.version,'status',version.status,'changeSummary',version.change_summary,'publishedAt',version.published_at)order by template.name,version.version desc),'[]')from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id),
  'featureFlags',(select coalesce(jsonb_agg(jsonb_build_object('key',key,'name',name,'description',description,'enabled',is_enabled,'rolloutPercentage',rollout_percentage,'updatedAt',updated_at)order by name),'[]')from public.platform_feature_flags),
  'supportRequests',(select coalesce(jsonb_agg(jsonb_build_object('id',request.id,'businessId',request.organization_id,'businessName',organization.display_name,'reason',request.reason,'scopes',request.requested_scopes,'expiresAt',request.expires_at,'status',request.status,'requestedBy',request.requested_by,'reviewedBy',request.reviewed_by,'accessEnabled',request.access_enabled,'createdAt',request.created_at)order by request.created_at desc),'[]')from public.platform_support_access_requests request join public.organizations organization on organization.id=request.organization_id),
  'health',(select coalesce(jsonb_agg(jsonb_build_object('service',service,'status',status,'message',message,'checkedAt',checked_at)order by service),'[]')from public.platform_health_checks),
  'aiUsage',jsonb_build_object('trackedRequests',(select coalesce(sum(request_count),0)from public.platform_ai_usage_events),'inputTokens',(select coalesce(sum(input_tokens),0)from public.platform_ai_usage_events),'outputTokens',(select coalesce(sum(output_tokens),0)from public.platform_ai_usage_events),'advisorConversations',(select count(*)from public.ai_advisor_conversations),'builderSessions',(select count(*)from public.ai_system_builder_sessions),'recommendations',(select count(*)from public.ai_recommendations)),
  'platformAudit',(select coalesce(jsonb_agg(value),'[]')from(select jsonb_build_object('id',event.id,'actorUserId',event.actor_user_id,'action',event.action,'entity',event.entity_type,'entityId',event.entity_id,'timestamp',event.occurred_at)as value from public.platform_admin_audit_events event order by event.occurred_at desc limit 50)recent)
 )into result;return result;
end$$;

create function private.require_platform_manager()returns void language plpgsql stable security definer set search_path=''as $$begin if not private.is_platform_administrator(array['super_admin','platform_admin'])then raise exception'Permission denied.'using errcode='42501';end if;end$$;
create function public.save_platform_feature_flag(requested_key text,requested_name text,requested_description text,requested_enabled boolean,requested_rollout integer)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if requested_key!~'^[a-z][a-z0-9_]{0,79}$'or char_length(btrim(requested_name))not between 1 and 120 or requested_rollout not between 0 and 100 then raise exception'Invalid feature flag.'using errcode='22023';end if;select to_jsonb(flag)into previous from public.platform_feature_flags flag where key=requested_key;insert into public.platform_feature_flags(key,name,description,is_enabled,rollout_percentage,updated_by)values(requested_key,btrim(requested_name),left(coalesce(requested_description,''),1000),requested_enabled,requested_rollout,(select auth.uid()))on conflict(key)do update set name=excluded.name,description=excluded.description,is_enabled=excluded.is_enabled,rollout_percentage=excluded.rollout_percentage,updated_by=excluded.updated_by;select to_jsonb(flag)into next_value from public.platform_feature_flags flag where key=requested_key;perform private.write_platform_admin_audit(case when previous is null then'feature_flag.created'else'feature_flag.updated'end,'feature_flag',requested_key,previous,next_value);end$$;
create function public.set_platform_module_status(requested_key text,requested_status text)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if requested_status not in('draft','published','retired')then raise exception'Invalid module status.'using errcode='22023';end if;select to_jsonb(module)into previous from public.module_definitions module where key=requested_key for update;if previous is null then raise exception'Module not found.'using errcode='22023';end if;update public.module_definitions set status=requested_status,updated_at=now()where key=requested_key;select to_jsonb(module)into next_value from public.module_definitions module where key=requested_key;perform private.write_platform_admin_audit('module.status_changed','module',requested_key,previous,next_value);end$$;
create function public.set_platform_template_status(requested_template_id uuid,requested_status text)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if requested_status not in('draft','published','retired')then raise exception'Invalid template status.'using errcode='22023';end if;select to_jsonb(template)into previous from public.business_os_templates template where id=requested_template_id for update;if previous is null then raise exception'Template not found.'using errcode='22023';end if;update public.business_os_templates set status=requested_status,updated_at=now()where id=requested_template_id;select to_jsonb(template)into next_value from public.business_os_templates template where id=requested_template_id;perform private.write_platform_admin_audit('template.status_changed','business_os_template',requested_template_id::text,previous,next_value);end$$;
create function public.create_platform_template_version(requested_template_id uuid,requested_definition jsonb,requested_change_summary text)returns uuid language plpgsql security definer set search_path=''as $$declare target uuid:=gen_random_uuid();next_version integer;begin perform private.require_platform_manager();if not private.business_os_definition_is_valid(requested_definition)or char_length(btrim(requested_change_summary))not between 1 and 500 or not exists(select 1 from public.business_os_templates where id=requested_template_id)then raise exception'Invalid template version.'using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended(requested_template_id::text,0));select coalesce(max(version),0)+1 into next_version from public.business_os_template_versions where template_id=requested_template_id;insert into public.business_os_template_versions(id,template_id,version,definition,change_summary,status)values(target,requested_template_id,next_version,requested_definition,btrim(requested_change_summary),'draft');perform private.write_platform_admin_audit('template_version.created','business_os_template_version',target::text,null,jsonb_build_object('templateId',requested_template_id,'version',next_version,'status','draft','changeSummary',requested_change_summary));return target;end$$;
create function public.publish_platform_template_version(requested_version_id uuid)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();select to_jsonb(version_row)into previous from public.business_os_template_versions version_row where id=requested_version_id and status='draft'for update;if previous is null then raise exception'Only a draft template version can be published.'using errcode='P0001';end if;update public.business_os_template_versions set status='published',published_at=now(),updated_at=now()where id=requested_version_id;select to_jsonb(version_row)into next_value from public.business_os_template_versions version_row where id=requested_version_id;perform private.write_platform_admin_audit('template_version.published','business_os_template_version',requested_version_id::text,previous,next_value);end$$;
create function public.set_platform_business_status(requested_organization_id uuid,requested_status text)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if requested_status not in('active','suspended','archived')then raise exception'Invalid business status.'using errcode='22023';end if;select jsonb_build_object('id',id,'status',status)into previous from public.organizations where id=requested_organization_id for update;if previous is null then raise exception'Business not found.'using errcode='22023';end if;update public.organizations set status=requested_status,updated_at=now()where id=requested_organization_id;select jsonb_build_object('id',id,'status',status)into next_value from public.organizations where id=requested_organization_id;perform private.write_platform_admin_audit('business.status_changed','business',requested_organization_id::text,previous,next_value);end$$;
create function public.set_platform_subscription(requested_organization_id uuid,requested_plan text,requested_status text)returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if not exists(select 1 from public.plans where key=requested_plan)or requested_status not in('trialing','active','grace_period','expired','canceled','paused')then raise exception'Invalid subscription state.'using errcode='22023';end if;select jsonb_build_object('plan',plan_key,'status',status)into previous from public.subscriptions where organization_id=requested_organization_id for update;insert into public.subscriptions(organization_id,plan_key,status,provider,started_at,entitlements)values(requested_organization_id,requested_plan,requested_status,'internal',now(),'{}')on conflict(organization_id)do update set plan_key=excluded.plan_key,status=excluded.status,updated_at=now(),version=public.subscriptions.version+1;select jsonb_build_object('plan',plan_key,'status',status)into next_value from public.subscriptions where organization_id=requested_organization_id;perform private.write_platform_admin_audit('subscription.changed','subscription',requested_organization_id::text,previous,next_value);end$$;
create function public.request_platform_support_access(requested_organization_id uuid,requested_reason text,requested_scopes text[],requested_expires_at timestamptz)returns uuid language plpgsql security definer set search_path=''as $$declare target uuid:=gen_random_uuid();begin if not private.is_platform_administrator(array['super_admin','platform_admin','support_admin'])then raise exception'Permission denied.'using errcode='42501';end if;if char_length(btrim(requested_reason))not between 20 and 1000 or cardinality(requested_scopes)not between 1 and 20 or exists(select 1 from unnest(requested_scopes)item where item!~'^[a-z][a-z0-9_.-]{0,79}$')or requested_expires_at<=now()or requested_expires_at>now()+interval'24 hours'then raise exception'Invalid support access request.'using errcode='22023';end if;insert into public.platform_support_access_requests(id,organization_id,requested_by,reason,requested_scopes,expires_at)values(target,requested_organization_id,(select auth.uid()),btrim(requested_reason),requested_scopes,requested_expires_at);perform private.write_platform_admin_audit('support_access.requested','support_access',target::text,null,jsonb_build_object('businessId',requested_organization_id,'scopes',requested_scopes,'expiresAt',requested_expires_at,'accessEnabled',false));return target;end$$;
create function public.review_platform_support_access(requested_request_id uuid,requested_approve boolean)returns void language plpgsql security definer set search_path=''as $$declare request public.platform_support_access_requests%rowtype;previous jsonb;next_value jsonb;begin perform private.require_platform_manager();select*into request from public.platform_support_access_requests where id=requested_request_id for update;if request.id is null or request.status<>'requested'or request.requested_by=(select auth.uid())then raise exception'Support request cannot be reviewed.'using errcode='P0001';end if;previous=to_jsonb(request);update public.platform_support_access_requests set status=case when requested_approve then'approved_pending_customer'else'rejected'end,reviewed_by=(select auth.uid()),reviewed_at=now(),updated_at=now()where id=request.id;select to_jsonb(value)into next_value from public.platform_support_access_requests value where id=request.id;perform private.write_platform_admin_audit(case when requested_approve then'support_access.platform_approved'else'support_access.rejected'end,'support_access',request.id::text,previous,next_value);end$$;
create function public.update_platform_health_check(requested_service text,requested_status text,requested_message text,requested_metrics jsonb default'{}')returns void language plpgsql security definer set search_path=''as $$declare previous jsonb;next_value jsonb;begin perform private.require_platform_manager();if requested_service!~'^[a-z][a-z0-9_]{0,79}$'or requested_status not in('healthy','degraded','down','unknown')or char_length(requested_message)>500 or jsonb_typeof(requested_metrics)<>'object'then raise exception'Invalid health check.'using errcode='22023';end if;select to_jsonb(check_value)into previous from public.platform_health_checks check_value where service=requested_service;insert into public.platform_health_checks(service,status,message,metrics,checked_at,updated_by)values(requested_service,requested_status,requested_message,requested_metrics,now(),(select auth.uid()))on conflict(service)do update set status=excluded.status,message=excluded.message,metrics=excluded.metrics,checked_at=excluded.checked_at,updated_by=excluded.updated_by;select to_jsonb(check_value)into next_value from public.platform_health_checks check_value where service=requested_service;perform private.write_platform_admin_audit('health_check.updated','platform_health',requested_service,previous,next_value);end$$;

alter table public.platform_administrators enable row level security;alter table public.platform_admin_audit_events enable row level security;alter table public.platform_feature_flags enable row level security;alter table public.platform_business_feature_overrides enable row level security;alter table public.platform_ai_usage_events enable row level security;alter table public.platform_health_checks enable row level security;alter table public.platform_support_access_requests enable row level security;
create policy platform_administrators_read on public.platform_administrators for select to authenticated using(private.is_platform_administrator());
create policy platform_admin_audit_read on public.platform_admin_audit_events for select to authenticated using(private.is_platform_administrator());
create policy platform_feature_flags_read on public.platform_feature_flags for select to authenticated using(private.is_platform_administrator());
create policy platform_feature_overrides_read on public.platform_business_feature_overrides for select to authenticated using(private.is_platform_administrator());
create policy platform_ai_usage_read on public.platform_ai_usage_events for select to authenticated using(private.is_platform_administrator());
create policy platform_health_read on public.platform_health_checks for select to authenticated using(private.is_platform_administrator());
create policy platform_support_read on public.platform_support_access_requests for select to authenticated using(private.is_platform_administrator());
revoke all on table public.platform_administrators,public.platform_admin_audit_events,public.platform_feature_flags,public.platform_business_feature_overrides,public.platform_ai_usage_events,public.platform_health_checks,public.platform_support_access_requests from public,anon,authenticated;
grant select on table public.platform_administrators,public.platform_admin_audit_events,public.platform_feature_flags,public.platform_business_feature_overrides,public.platform_ai_usage_events,public.platform_health_checks,public.platform_support_access_requests to authenticated;
revoke all on function private.is_platform_administrator(text[]),private.write_platform_admin_audit(text,text,text,jsonb,jsonb),private.reject_platform_audit_mutation(),private.require_platform_manager()from public,anon,authenticated;
grant execute on function private.is_platform_administrator(text[])to authenticated;
revoke all on function public.platform_admin_dashboard(),public.save_platform_feature_flag(text,text,text,boolean,integer),public.set_platform_module_status(text,text),public.set_platform_template_status(uuid,text),public.create_platform_template_version(uuid,jsonb,text),public.publish_platform_template_version(uuid),public.set_platform_business_status(uuid,text),public.set_platform_subscription(uuid,text,text),public.request_platform_support_access(uuid,text,text[],timestamptz),public.review_platform_support_access(uuid,boolean),public.update_platform_health_check(text,text,text,jsonb)from public,anon;
grant execute on function public.platform_admin_dashboard(),public.save_platform_feature_flag(text,text,text,boolean,integer),public.set_platform_module_status(text,text),public.set_platform_template_status(uuid,text),public.create_platform_template_version(uuid,jsonb,text),public.publish_platform_template_version(uuid),public.set_platform_business_status(uuid,text),public.set_platform_subscription(uuid,text,text),public.request_platform_support_access(uuid,text,text[],timestamptz),public.review_platform_support_access(uuid,boolean),public.update_platform_health_check(text,text,text,jsonb)to authenticated;

comment on table public.platform_administrators is'Explicit platform role assignment. It is intentionally independent from organization membership and never participates in tenant RLS.';
comment on table public.platform_ai_usage_events is'Usage-only AI telemetry. Prompts, responses, and conversation content are prohibited.';
comment on table public.platform_support_access_requests is'Dual-review support-access preparation. No tenant policy consumes this table, so approval does not grant customer-data access.';
